$needles = @('"'TestCaseFilter','Category"'!=AiReview'"','Category"'!=Integration'"','ExactFinalEvidenceTag')
"'$needleEvidence = foreach ($needle in $needles) {
  $index = $raw.IndexOf($needle, [System.StringComparison]::OrdinalIgnoreCase)
